import{_ as a,o as e,c as r,a2 as d}from"./chunks/framework.kOe0DhAP.js";const p=JSON.parse('{"title":"数据存储与缓存","description":"区分业务事实、运行态数据和查询视图。","frontmatter":{"title":"数据存储与缓存","description":"区分业务事实、运行态数据和查询视图。"},"headers":[],"relativePath":"architecture/data.md","filePath":"architecture/data.md"}'),o={name:"architecture/data.md"};function i(c,t,h,l,n,s){return e(),r("div",null,[...t[0]||(t[0]=[d('<div class="doc-eyebrow">系统架构 / TGEX KNOWLEDGE BASE</div><h1 id="数据存储与缓存" tabindex="-1">数据存储与缓存 <a class="header-anchor" href="#数据存储与缓存" aria-label="Permalink to &quot;数据存储与缓存&quot;">​</a></h1><div class="doc-lead">区分业务事实、运行态数据和查询视图。</div><h2 id="数据分工" tabindex="-1">数据分工 <a class="header-anchor" href="#数据分工" aria-label="Permalink to &quot;数据分工&quot;">​</a></h2><p>业务数据库记录账户、委托、成交、配置等持久化信息。缓存与撮合内存承担快速访问和运行状态维护。搜索索引、报表与推送属于面向查询的派生视图。</p><h2 id="数据关系" tabindex="-1">数据关系 <a class="header-anchor" href="#数据关系" aria-label="Permalink to &quot;数据关系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>对象</th><th>必须回答的问题</th></tr></thead><tbody><tr><td>订单</td><td>谁在什么规则下提交了多少数量？</td></tr><tr><td>成交</td><td>哪些订单以什么价格完成了多少交易？</td></tr><tr><td>流水</td><td>哪个业务事实导致哪类资产发生变化？</td></tr><tr><td>缓存</td><td>数据从哪里加载，何时更新，失效后如何恢复？</td></tr></tbody></table><h2 id="恢复设计" tabindex="-1">恢复设计 <a class="header-anchor" href="#恢复设计" aria-label="Permalink to &quot;恢复设计&quot;">​</a></h2><p>在已检查的现货撮合实现中，可见未完成委托查询、初始化撮合事件以及本地存储相关逻辑。恢复时不仅要重建盘口，还要确认恢复边界，防止历史成交或资金事件被重复应用。</p><p>缓存与持久化之间的具体权威关系必须逐服务确认，不能一概把缓存称为可随时丢弃的数据。</p>',10)])])}const u=a(o,[["render",i]]);export{p as __pageData,u as default};
